SELECT CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CASE WHEN unit_price >= 310 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, order_id, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, CORR(quantity, unit_price) AS corr_quantity_unit_price, BIT_OR(quantity) AS quantity_bit_or, PERCENT_RANK() OVER (PARTITION BY CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END ORDER BY BIT_OR(quantity) DESC) AS quantity_bit_or_percent_rank FROM order_items GROUP BY 1, 2, 3 ORDER BY unit_price_tier
